example.query:
mutation InitiatePayment($input: PaymentInitiationRequestInput!) {
  clientPaymentInitiationRequestCreate(input: $input) {
    paymentInitiationRequest {
      id
      url
      status
    }
  }
}

query ListBankAccounts {
  user {
    bankAccounts {
      id
      name
      accountNumber
      bankId
      availableBalance { quantity currency }
      currentBalance { quantity currency }
    }
  }
}
